"use client";

import { useState } from "react";

export const X = [1, 2, 3, 4, 5, 6, 7, 8];
export const REL: [number, number][] = [[1, 2], [2, 3], [4, 5], [6, 7], [7, 8], [8, 6]];

/** Classes of the equivalence relation on X generated by the chosen pairs. */
export function classes(on: boolean[]) {
  const parent = new Map(X.map((x) => [x, x]));
  const find = (x: number): number => (parent.get(x) === x ? x : find(parent.get(x)!));
  REL.forEach(([a, b], i) => { if (on[i]) parent.set(find(a), find(b)); });
  const groups = new Map<number, number[]>();
  X.forEach((x) => { const r = find(x); groups.set(r, [...(groups.get(r) ?? []), x]); });
  return [...groups.values()];
}

/** The coequaliser of two maps R → X in sets: X modulo the equivalence relation generated by R. */
export function CoequaliserViz() {
  const [on, setOn] = useState([true, false, true, false, false, false]);
  const cl = classes(on);
  const pos = (x: number) => [60 + ((x - 1) % 4) * 140, x <= 4 ? 60 : 160];
  const colour = (x: number) => {
    const i = cl.findIndex((c) => c.includes(x));
    return ["var(--accent)", "var(--success)", "var(--danger)", "var(--text-muted)", "var(--accent)", "var(--success)", "var(--danger)", "var(--text-muted)"][i];
  };
  return (
    <figure className="viz">
      <div className="segmented" role="group" aria-label="relations">
        {REL.map(([a, b], i) => <button key={i} type="button" aria-pressed={on[i]} className={on[i] ? "seg is-on" : "seg"} onClick={() => setOn((o) => o.map((v, j) => (j === i ? !v : v)))}>{a} ~ {b}</button>)}
      </div>
      <svg viewBox="0 0 540 220" role="img" aria-label="Eight points with chosen identifications, grouped into classes" style={{ width: "100%", display: "block", marginTop: 8 }}>
        {REL.map(([a, b], i) => {
          if (!on[i]) return null;
          const [x1, y1] = pos(a), [x2, y2] = pos(b);
          const bend = a === 8 && b === 6 ? 40 : 0;
          return <path key={i} d={`M${x1},${y1} Q${(x1 + x2) / 2},${(y1 + y2) / 2 + bend} ${x2},${y2}`} style={{ fill: "none", stroke: "var(--border-strong)", strokeWidth: 3 }} />;
        })}
        {X.map((x) => {
          const [cx, cy] = pos(x);
          return (
            <g key={x}>
              <circle cx={cx} cy={cy} r={18} style={{ fill: "var(--surface)", stroke: colour(x), strokeWidth: 3 }} />
              <text x={cx} y={cy + 5} textAnchor="middle" style={{ fill: "var(--text)", fontSize: 14, fontWeight: 700 }}>{x}</text>
            </g>
          );
        })}
      </svg>
      <p className="mono" style={{ fontSize: 13, fontWeight: 700 }}>
        The coequaliser has {cl.length} elements: {cl.map((c) => `{${c.join(", ")}}`).join(" ")}.
      </p>
      <figcaption className="viz-caption">
        Each chosen pair (a, b) is an element r of R with f(r) = a and g(r) = b. The coequaliser of f and g is the quotient
        of X by the smallest equivalence relation containing these pairs: the universal way to force f and g to become
        equal. Gluing is transitive, so 1 ~ 2 and 2 ~ 3 identify 1 with 3 as well.
      </figcaption>
    </figure>
  );
}
